esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // accept ETH so this contract can forward donations
    receive() external payable {}

    // params: amount to donate (must be <= this contract balance so we can forward it)
    function run(uint256 donateAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (donateAmount)); require(donateAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= donateAmount);

        // Make the deployed contract open to public. This test contract is the owner (deployer of c).
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        // Read balance before donate
        uint256 beforeBalance = address(c).balance;

        // Attempt to call donate{value: donateAmount} and observe revert or success
        bool didRevert;
        c.donate{value: donateAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // Read balance after donate (even if call reverted, balance should be unchanged)
        uint256 afterBalance = address(c).balance;

        // General rule: after a donate call (whether it reverted or not), the contract's balance
        // cannot have increased by more than the forwarded donateAmount.
        // (covers cases where donate forwards funds to whale or keeps them; it should never magically gain > donated)
        assert(afterBalance <= beforeBalance + donateAmount);
    }
}

